<?php
 namespace QQWorld\Backend\Test\Constraint; use QQWorld\Store\Test\Fixture\Store; use QQWorld\Mtf\Constraint\AbstractConstraint; use QQWorld\Backend\Test\Page\Adminhtml\SystemConfig; use QQWorld\Cms\Test\Page\CmsIndex; use QQWorld\PageCache\Test\Page\Adminhtml\AdminCache; class AssertStoreCanBeLocalized extends AbstractConstraint { public function processAssert( SystemConfig $systemConfig, Store $store, CmsIndex $cmsIndex, AdminCache $adminCache, $locale, $welcomeText ) { $systemConfig->open(); $systemConfig->getPageActions()->selectStore($store->getGroupId() . "/" . $store->getName()); $systemConfig->getModalBlock()->acceptAlert(); $configGroup = $systemConfig->getForm()->getGroup('general', 'locale', 'code'); $configGroup->setValue('general', 'locale', 'code', $locale); $systemConfig->getPageActions()->save(); $systemConfig->getMessagesBlock()->waitSuccessMessage(); $adminCache->open(); $adminCache->getActionsBlock()->flushQQWorldCache(); $adminCache->getMessagesBlock()->waitSuccessMessage(); $cmsIndex->open(); if ($cmsIndex->getFooterBlock()->isStoreGroupSwitcherVisible() && $cmsIndex->getFooterBlock()->isStoreGroupVisible($store) ) { $cmsIndex->getFooterBlock()->selectStoreGroup($store); } $cmsIndex->getStoreSwitcherBlock()->selectStoreView($store->getName()); \PHPUnit_Framework_Assert::assertTrue( $cmsIndex->getSearchBlock()->isPlaceholderContains($welcomeText), "Locale not applied." ); } public function toString() { return 'Store locale has changed successfully.'; } } 